wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(41350826359878700320)
,p_plug_name=>'Inventory Summary'
,p_static_id=>'inventory-summary'
,p_title=>'Inventory Summary'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ''Total Products'' AS title, ',
'    TO_CHAR(COUNT(*)) AS value, ',
'    ''fa-box'' AS card_icon, ',
'    1 AS seq ',
'FROM VW_STORE_INVENTORY',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Active Suppliers'' AS title, ',
'    TO_CHAR(COUNT(*)) AS value, ',
'    ''fa-users'' AS card_icon, ',
'    2 AS seq ',
'FROM STORE_SUPPLIERS ',
'WHERE status = ''ACTIVE''',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Total Inventory Value ($)'' AS title, ',
'    TO_CHAR(NVL(SUM(inventory_value), 0), ''FM999,999,990.00'') AS value, ',
'    ''fa-dollar'' AS card_icon, ',
'    3 AS seq ',
'FROM VW_STORE_INVENTORY',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Low Stock Alerts'' AS title, ',
'    TO_CHAR(COUNT(*)) AS value, ',
'    ''fa-warning'' AS card_icon, ',
'    4 AS seq ',
'FROM VW_STORE_INVENTORY ',
'WHERE stock_status = ''LOW STOCK''',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Out of Stock'' AS title, ',
'    TO_CHAR(COUNT(*)) AS value, ',
'    ''fa-exclamation-triangle'' AS card_icon, ',
'    5 AS seq ',
'FROM VW_STORE_INVENTORY ',
'WHERE stock_status = ''OUT OF STOCK''',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Potential Sales Value'' AS title, ',
'    TO_CHAR(NVL(SUM(potential_sales_value), 0), ''FM999,999,990.00'') AS value, ',
'    ''fa-line-chart'' AS card_icon, ',
'    6 AS seq ',
'FROM VW_STORE_INVENTORY',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Potential Gross Margin'' AS title, ',
'    TO_CHAR(NVL(SUM(potential_profit), 0), ''FM999,999,990.00'') AS value, ',
'    ''fa-pie-chart'' AS card_icon, ',
'    7 AS seq ',
'FROM VW_STORE_INVENTORY',
'ORDER BY seq;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
