wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(41350827009557700327)
,p_validation_name=>'CHK_SUFFICIENT_STOCK'
,p_static_id=>'chk-sufficient-stock'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_current_stock NUMBER;',
'BEGIN',
'    IF :P7_TRANSACTION_TYPE IN (''SALE'', ''ADJUSTMENT_OUT'') THEN',
'        SELECT stock_qty INTO v_current_stock',
'        FROM STORE_GROCERIES',
'        WHERE product_id = :P7_PRODUCT_ID;',
'',
'        IF :P7_QUANTITY > v_current_stock THEN',
'            RETURN ''Insufficient stock! Current available stock is '' || v_current_stock || ''.'';',
'        END IF;',
'    END IF;',
'    RETURN NULL;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''Selected product does not exist.'';',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
